import{_ as e,o as a,c as t,a2 as l}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Настройка канала Slack","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/channels/slack.md","filePath":"ru/integrations/channels/slack.md","lastUpdated":1792323081000}'),c={name:"ru/integrations/channels/slack.md"};function r(i,o,s,n,d,h){return a(),t("div",null,[...o[0]||(o[0]=[l('<h1 id="настроика-канала-slack" tabindex="-1">Настройка канала Slack <a class="header-anchor" href="#настроика-канала-slack" aria-label="Permalink to &quot;Настройка канала Slack&quot;">​</a></h1><p>Подключите своего Bot в Memoh к Slack: он сможет получать личные сообщения, работать в каналах и тредах, читать вложения, отправлять файлы и отвечать в потоковом режиме.</p><h2 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h2><ul><li>Рабочее пространство Slack, в которое вы можете устанавливать приложения, и доступ к <a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">консоли Slack API</a>.</li><li>Bot в Memoh; каналы настраиваются на его вкладке <strong>Platforms</strong>.</li></ul><h2 id="шаги" tabindex="-1">Шаги <a class="header-anchor" href="#шаги" aria-label="Permalink to &quot;Шаги&quot;">​</a></h2><h3 id="_1-в-консоли-slack-создаите-приложение" tabindex="-1">1. В консоли Slack создайте приложение <a class="header-anchor" href="#_1-в-консоли-slack-создаите-приложение" aria-label="Permalink to &quot;1. В консоли Slack создайте приложение&quot;">​</a></h3><ol><li>Откройте <a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">консоль Slack API</a> и создайте новое приложение.</li><li>Выберите рабочее пространство, куда хотите установить Bot.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Не закрывайте страницу настроек приложения — шаги со 2-го по 5-й выполняются именно там.</p></div><h3 id="_2-в-консоли-slack-включите-socket-mode" tabindex="-1">2. В консоли Slack включите Socket Mode <a class="header-anchor" href="#_2-в-консоли-slack-включите-socket-mode" aria-label="Permalink to &quot;2. В консоли Slack включите Socket Mode&quot;">​</a></h3><p>Адаптер Slack в Memoh работает через Socket Mode, поэтому помимо токена Bot понадобится ещё и app-level токен.</p><ol><li>В разделе <strong>Basic Information</strong> включите <strong>Socket Mode</strong>.</li><li>Создайте <strong>App-Level Token</strong> со scope <code>connections:write</code>.</li><li>Скопируйте сгенерированный токен. Он начинается с <code>xapp-</code>.</li></ol><h3 id="_3-в-консоли-slack-добавьте-scope-для-токена-bot" tabindex="-1">3. В консоли Slack добавьте scope для токена Bot <a class="header-anchor" href="#_3-в-консоли-slack-добавьте-scope-для-токена-bot" aria-label="Permalink to &quot;3. В консоли Slack добавьте scope для токена Bot&quot;">​</a></h3><p>В разделе <strong>OAuth &amp; Permissions</strong> добавьте scope токена Bot, которые нужны адаптеру Slack:</p><ul><li><code>app_mentions:read</code> — получать упоминания Bot в каналах</li><li><code>channels:history</code> — читать сообщения в публичных каналах</li><li><code>groups:history</code> — читать сообщения в приватных каналах</li><li><code>im:history</code> — читать личные сообщения</li><li><code>mpim:history</code> — читать групповые личные сообщения</li><li><code>chat:write</code> — отправлять ответы и сообщения в тредах</li><li><code>files:read</code> — читать загруженные файлы и изображения</li><li><code>files:write</code> — отправлять исходящие файлы</li><li><code>reactions:write</code> — ставить и убирать реакции</li></ul><p>Если хотите, чтобы названия бесед Slack и метаданные отображались в Memoh полнее, добавьте также рекомендуемые scope:</p><ul><li><code>channels:read</code></li><li><code>groups:read</code></li><li><code>im:read</code></li><li><code>mpim:read</code></li></ul><h3 id="_4-в-консоли-slack-подпишитесь-на-события-bot" tabindex="-1">4. В консоли Slack подпишитесь на события Bot <a class="header-anchor" href="#_4-в-консоли-slack-подпишитесь-на-события-bot" aria-label="Permalink to &quot;4. В консоли Slack подпишитесь на события Bot&quot;">​</a></h3><p>В разделе <strong>Event Subscriptions</strong> включите события Bot и добавьте входящие типы событий, которые обрабатывает адаптер Slack:</p><ul><li><code>app_mention</code></li><li><code>message.channels</code></li><li><code>message.groups</code></li><li><code>message.im</code></li><li><code>message.mpim</code></li></ul><h3 id="_5-в-консоли-slack-установите-приложение-в-рабочее-пространство" tabindex="-1">5. В консоли Slack установите приложение в рабочее пространство <a class="header-anchor" href="#_5-в-консоли-slack-установите-приложение-в-рабочее-пространство" aria-label="Permalink to &quot;5. В консоли Slack установите приложение в рабочее пространство&quot;">​</a></h3><ol><li>В разделе <strong>OAuth &amp; Permissions</strong> нажмите <strong>Install to Workspace</strong>.</li><li>Просмотрите экран запроса прав и авторизуйте приложение.</li><li>Скопируйте <strong>Bot User OAuth Token</strong>. Он начинается с <code>xoxb-</code>.</li></ol><h3 id="_6-в-memoh-добавьте-канал-slack" tabindex="-1">6. В Memoh добавьте канал Slack <a class="header-anchor" href="#_6-в-memoh-добавьте-канал-slack" aria-label="Permalink to &quot;6. В Memoh добавьте канал Slack&quot;">​</a></h3><ol><li>Откройте страницу нужного Bot и перейдите на вкладку <strong>Platforms</strong>.</li><li>Нажмите <strong>Add Channel</strong> и выберите <strong>Slack</strong>.</li><li>Заполните поля: <ul><li><strong>Bot Token</strong>: ваш токен <code>xoxb-...</code></li><li><strong>App-Level Token</strong>: ваш токен <code>xapp-...</code></li></ul></li><li>Нажмите <strong>Save and Enable</strong>.</li></ol><h3 id="_7-в-slack-добавьте-bot-в-беседы" tabindex="-1">7. В Slack добавьте Bot в беседы <a class="header-anchor" href="#_7-в-slack-добавьте-bot-в-беседы" aria-label="Permalink to &quot;7. В Slack добавьте Bot в беседы&quot;">​</a></h3><p>После включения канала приложение Slack ещё нужно добавить в те беседы, где оно должно работать:</p><ul><li>Личные сообщения: откройте DM с приложением и отправьте сообщение.</li><li>Публичные каналы: пригласите Bot в канал.</li><li>Приватные каналы: после установки пригласите Bot явно.</li></ul><h2 id="учетные-данные" tabindex="-1">Учётные данные <a class="header-anchor" href="#учетные-данные" aria-label="Permalink to &quot;Учётные данные&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Bot Token</strong></td><td><strong>Bot User OAuth Token</strong> (<code>xoxb-...</code>), скопированный после установки приложения в рабочее пространство.</td></tr><tr><td><strong>App-Level Token</strong></td><td>Токен Socket Mode (<code>xapp-...</code>), созданный со scope <code>connections:write</code>.</td></tr></tbody></table><p>Оба токена должны принадлежать одному и тому же приложению Slack и одному рабочему пространству.</p><h2 id="проверка" tabindex="-1">Проверка <a class="header-anchor" href="#проверка" aria-label="Permalink to &quot;Проверка&quot;">​</a></h2><p>Пригласите Bot в канал и отправьте ему <code>/help</code> через @-упоминание — или отправьте <code>/help</code> в личной переписке с приложением. Если Bot ответил списком команд, канал работает.</p><h2 id="групповые-чаты" tabindex="-1">Групповые чаты <a class="header-anchor" href="#групповые-чаты" aria-label="Permalink to &quot;Групповые чаты&quot;">​</a></h2><p>Каналы Slack поддерживаются. Пригласите Bot в публичный или приватный канал и общайтесь с ним через @-упоминания. Ответы могут продолжаться в тредах; Slack — единственный канал, поддерживающий треды.</p><h2 id="отключение-и-смена-учетных-данных" tabindex="-1">Отключение и смена учётных данных <a class="header-anchor" href="#отключение-и-смена-учетных-данных" aria-label="Permalink to &quot;Отключение и смена учётных данных&quot;">​</a></h2><p>Отключить или удалить этот канал можно в любой момент на вкладке <strong>Platforms</strong> нужного Bot. Чтобы сменить учётные данные, обновите поля <strong>Bot Token</strong> и <strong>App-Level Token</strong> и сохраните.</p><h2 id="faq" tabindex="-1">Частые вопросы <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;Частые вопросы {#faq}&quot;">​</a></h2><h3 id="why-two-tokens" tabindex="-1">Зачем Slack два токена? <a class="header-anchor" href="#why-two-tokens" aria-label="Permalink to &quot;Зачем Slack два токена? {#why-two-tokens}&quot;">​</a></h3><p>Адаптер Slack в Memoh работает через Socket Mode: помимо токена Bot <code>xoxb-...</code> нужен ещё app-level токен <code>xapp-...</code>, и оба должны принадлежать одному приложению Slack и одному рабочему пространству.</p><h3 id="cannot-read-files" tabindex="-1">Bot отправляет сообщения, но не читает загруженные изображения и файлы <a class="header-anchor" href="#cannot-read-files" aria-label="Permalink to &quot;Bot отправляет сообщения, но не читает загруженные изображения и файлы {#cannot-read-files}&quot;">​</a></h3><p>Проверьте, что включён scope <code>files:read</code>.</p><h3 id="no-incoming-messages" tabindex="-1">Bot подключается, но не получает входящих сообщений <a class="header-anchor" href="#no-incoming-messages" aria-label="Permalink to &quot;Bot подключается, но не получает входящих сообщений {#no-incoming-messages}&quot;">​</a></h3><p>Перепроверьте события Bot в разделе <strong>Event Subscriptions</strong> и соответствующие scope вида <code>history</code>.</p>',42)])])}const m=e(c,[["render",r]]);export{p as __pageData,m as default};
